arguments.command:
export AGENT_BROWSER_SESSION=resy-discovery-862eea5dd5b5
for day in $(seq -w 1 28); do
 agent-browser open "https://resy.com/cities/san-francisco-ca/venues/esme-ca?date=2026-10-$day&seats=2" >/dev/null || break
 agent-browser wait --fn "document.querySelector('.ReservationButtonList')!==null || document.body.innerText.includes('no online availability')" >/dev/null || break
 agent-browser eval --stdin <<'EOF'
const date=new URL(location.href).searchParams.get('date');
const slots=Array.from(document.querySelectorAll('button.ReservationButton')).map(b=>({time:b.querySelector('.ReservationButton__time')?.innerText,type:b.querySelector('.ReservationButton__type')?.innerText,exactText:b.innerText,displayedPrice:null}));
const qualifying=slots.filter(s=>{const m=s.time?.match(/(\d+):(\d+) (AM|PM)/);if(!m)return false;const minutes=(Number(m[1])%12+(m[3]==='PM'?12:0))*60+Number(m[2]);return minutes>=1080&&minutes<=1260;});
const monday=new Date(date+'T12:00:00Z').getUTCDay()===1;
({observedAt:new Date().toISOString(),diningDate:date,status:monday?'non_service':qualifying.length?'available':'unknown',qualifyingSlots:qualifying,allVisibleSlots:slots,exactText:Array.from(document.querySelectorAll('.ShiftInventory__availability-message,.ShiftInventory,.ReservationButtonList')).map(e=>e.innerText).filter((t,i,a)=>a.indexOf(t)===i),sourceUrl:location.href,selectedDate:document.querySelector('button[aria-label*="Selected date"]')?.getAttribute('aria-label'),guests:document.querySelector('select')?.value})
EOF
 done
